import {useStyle, type UseStyleResult, type GenerateStyle} from '@ant-design/pro-provider';
import {type ExtraProAliasToken} from '@/type/design-token';
import {PackageConst} from '@/constant/PackageConst';


const buildFieldStyle: GenerateStyle<ExtraProAliasToken> = (token) => {
    return {
        [`${token.componentCls}-popup`]: {
            [`${token.componentCls}-option`]: {
                display: 'flex',
                flexFlow: 'row nowrap',
            },
            [`${token.componentCls}-before-prior`]: {
                [`${token.componentCls}-option-before`]: {
                    flex: 1,
                    paddingRight: token.paddingXXS,
                },
                [`${token.componentCls}-option-after`]: {
                    flex: 'none',
                    width: 'fit-content',
                }
            },
            [`${token.componentCls}-after-prior`]: {
                [`${token.componentCls}-option-before`]: {
                    flex: 'none',
                    width: 'fit-content',
                },
                [`${token.componentCls}-option-after`]: {
                    flex: 1,
                    paddingLeft: token.paddingXXS,
                }
            },
            [`${token.antCls}-select-item-option-selected ${token.componentCls}-option span:last-of-type`]: {
                paddingRight: token.paddingXXS,
            }
        }
    };
}


export function useFieldStyle(prefixCls: string): UseStyleResult {
    return useStyle(`${PackageConst.PACKAGE_NAME}:DivideSelect`, (token) => {
        const mesh: ExtraProAliasToken = {
            prefixCls,
            componentCls: `.${prefixCls}`,
            ...token,
        };
        return [buildFieldStyle(mesh)];
    });
}
